<?php require_once __DIR__.'/../config/bootstrap.php';$token=$_GET['token']??$_POST['token']??'';$valid=false;$s=db()->prepare('SELECT pr.*,u.email FROM password_resets pr JOIN users u ON u.id=pr.user_id WHERE pr.token_hash=? AND pr.expires_at>NOW() AND pr.used_at IS NULL LIMIT 1');$s->execute([hash('sha256',$token)]);$r=$s->fetch();if($r)$valid=true;$err='';if($_SERVER['REQUEST_METHOD']==='POST'&&$valid){verify_csrf();$a=$_POST['senha']??'';$b=$_POST['confirmar']??'';if(strlen($a)<8||$a!==$b)$err='A senha precisa ter pelo menos 8 caracteres e coincidir.';else{db()->prepare('UPDATE users SET senha=? WHERE id=?')->execute([password_hash($a,PASSWORD_DEFAULT),$r['user_id']]);db()->prepare('UPDATE password_resets SET used_at=NOW() WHERE id=?')->execute([$r['id']]);flash('success','Senha alterada.');redirect('aluno/login.php');}} ?>
<?php layout_header('Nova senha'); ?><div class="auth-card"><h1>Nova senha</h1><p class="subtitle">Crie uma nova senha para sua conta.</p><?php if(!$valid): ?><div class="form-error">Link inválido ou expirado.</div><?php else: ?><?php if($err): ?><div class="form-error"><?=e($err)?></div><?php endif; ?><form method="post"><?=csrf_field()?><input type="hidden" name="token" value="<?=e($token)?>"><label>Nova senha</label><input type="password" name="senha" minlength="8" required><label>Confirmar senha</label><input type="password" name="confirmar" minlength="8" required><button class="btn">Salvar nova senha</button></form><?php endif; ?></div><?php layout_footer(); ?>
